import React, { useState } from 'react';

const HintSystem = ({ question, onHintUsed }) => {
  const [hintsUsed, setHintsUsed] = useState(0);
  const [showHint, setShowHint] = useState(false);

  const hints = [
    "💡 Think about the key concepts in this topic",
    "🔍 Consider the most logical or commonly accepted answer",
    "📚 Remember what you've learned about this subject",
    "🤔 Eliminate obviously wrong options first"
  ];

  const handleUseHint = () => {
    if (hintsUsed < hints.length) {
      setHintsUsed(hintsUsed + 1);
      setShowHint(true);
      onHintUsed && onHintUsed(hintsUsed + 1);
    }
  };

  const getHintText = () => {
    if (hintsUsed === 0) return hints[0];
    if (hintsUsed === 1) return "🎯 Focus on the specific details mentioned in the question";
    if (hintsUsed === 2) return "⚡ The answer is usually the most comprehensive option";
    return "🏆 You've used all hints! Trust your knowledge and make your best guess.";
  };

  return (
    <div style={{
      marginTop: '15px',
      padding: '15px',
      background: '#f7fafc',
      borderRadius: '10px',
      border: '1px solid #e2e8f0'
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '10px'
      }}>
        <h4 style={{
          margin: 0,
          fontSize: '1rem',
          color: '#4a5568'
        }}>
          Need Help? 💡
        </h4>
        <button
          onClick={handleUseHint}
          disabled={hintsUsed >= 3}
          style={{
            padding: '6px 12px',
            background: hintsUsed >= 3 ? '#cbd5e0' : '#667eea',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: hintsUsed >= 3 ? 'not-allowed' : 'pointer',
            fontSize: '0.9rem',
            fontWeight: '600',
            transition: 'all 0.3s ease'
          }}
        >
          {hintsUsed >= 3 ? 'All Hints Used' : `Use Hint ${hintsUsed + 1}/3`}
        </button>
      </div>
      
      {showHint && (
        <div style={{
          padding: '10px',
          background: '#edf2f7',
          borderRadius: '6px',
          border: '1px solid #cbd5e0',
          animation: 'slideUp 0.3s ease-out'
        }}>
          <p style={{
            margin: 0,
            fontSize: '0.9rem',
            color: '#4a5568',
            lineHeight: '1.4'
          }}>
            {getHintText()}
          </p>
        </div>
      )}
      
      {hintsUsed > 0 && (
        <div style={{
          marginTop: '10px',
          fontSize: '0.8rem',
          color: '#718096',
          textAlign: 'right'
        }}>
          Hints used: {hintsUsed}/3
        </div>
      )}
    </div>
  );
};

export default HintSystem;
